import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泽雷随","description":"周易折中 - 泽雷随","frontmatter":{"title":"泽雷随","description":"周易折中 - 泽雷随"},"headers":[],"relativePath":"zh/classics/zhezhong/023.md","filePath":"zh/classics/zhezhong/023.md"}'),h={name:"zh/classics/zhezhong/023.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="泽雷随" tabindex="-1">泽雷随 <a class="header-anchor" href="#泽雷随" aria-label="Permalink to “泽雷随”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>随序卦，豫必有随，故受之以随。夫悦豫之道，物所随也。随所以次豫也，为卦兑上震下兑为说，震为动，说而动，动而说，皆随之义。女随人者也，以少女从长男随之义也。又震为雷，兑为泽，雷震于泽中，泽随而动，随之象也。又以卦变言之，干之上来居坤之下，坤之初往居干之上，阳来下于阴也。以阳下阴，阴必说，随为随之义。凡成卦既取二体之义，又有取爻义者，复有更取卦变之义者。如随之取义尤为详备。</p><p>随：元亨利贞，无咎</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>随从也。以卦变言之，本自困卦九来居初，又自噬嗑九来居五，而自未济来者，兼此二变，皆刚来随柔之义。以二体言之，为此动而彼说，亦随之义，故为随。已能随物，物来随已，彼此相从，其通易矣。故其占为元亨，然必利于贞，乃得无咎。若所随不正，则虽大亨而不免于有咎矣。春秋传穆姜曰：“有是四德，随而无咎，我皆无之，岂随也哉？”今按，四德虽非本义，然其下云云，深得占法之意。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>随之道，可以致大亨也。君子之道，为众所随，与已随于人，及临事择所随，皆随也。随得其道，则可以致大亨也。凡人君之从善，臣下之奉命，学者之徙义，临事而从长，皆随也。随之道，利在于贞正。随得其正，然后能大亨而无咎。失其正，则有咎矣，岂能亨乎？</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>石氏介曰：凡随之义，可随则随，若唯随之务，不以正道，安得亨乎？</li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>以二体言之，震刚下兑柔。以卦画言之，刚爻下于柔爻，六十四卦中，惟此一卦。此卦名为随之第一义也。其象则如以贵下贱，以多问于寡，乃尧舜所谓舍己从人者，其义最大。故其辞曰元亨，又曰利贞无咎者，明所随必得其正，所以终元亨之义也。然则卦义所主在以己随人，至于物来随己，则其效也。若以为物所随为卦名之本义，则非矣。</p><p>象曰：泽中有雷，随；君子以向晦入宴息</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>雷藏泽中，随时休息。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷震于泽中，泽随震而动，为随之象。君子观象以随时而动，随时之宜，万事皆然。取其最明且近者言之，君子以向晦入宴息。君子昼则自强不息，及向昏晦，则入居于内，宴息以安其身，起居随时，适其宜也。礼，君子昼不居内，夜不居外，随时之道也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>翟氏玄曰 ：晦者，冥也。雷者，阳气，春夏用事，今在泽中，秋冬时也。故君子象之，日出视事，其将晦冥，退入宴寝而休息也。</p></li><li><p>朱子语类 ：问“程子云：‘泽随雷动，君子当随时宴息。’是否”？曰：“既曰雷动，何不言君子以动作，却言宴息？”盖其卦震下兑上，乃雷入地中之象，雷随时伏藏，故君子亦向晦入宴息。</p></li></ul><p>《彖》曰：随，刚来而下柔，动而说，随</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦变卦德释卦名义。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：刚谓震也，柔谓兑也。震处兑下，是刚来下柔。震动而兑说，既能下人，动则喜说，所以物皆随从也。</p></li><li><p>胡氏瑗曰：震以动，其性刚；兑以说，其性柔。今震在兑下，是刚来而下于柔也。犹圣贤君子以至刚之德，至尊之位，至贵之势，接于臣而下于民，故赏罚号令一出于上，则民皆说而随于下也。</p></li><li><p>王氏逢曰：上能下下，下之所以随上；贵能下贱，贱之所以随贵。随之义，刚下柔也。</p></li><li><p>王氏宗传曰：阳刚非在下之物也，今也得随之义，来下于阴柔，则是能以上下下，以贵下贱者也。物安得不随之乎？动而说，此有所动而彼无不说之谓也。彼无不说，则亦无不随矣。或曰：“易家以随自否来，蛊自泰来，其义如何？”曰：“非也。乾坤重而为泰否，故随、蛊无自泰否而来之理。世儒惑于卦变，殊不知八卦成列，因而重之，而内外上下往来之义已备乎其中。自八卦既重之后，又乌有所谓内外上下往来之义乎？”</p></li><li><p>蒋氏悌生曰：程传谓“说而动”与“动而说”皆随之义。朱子语录云：“但当言动而说，不当言说而动。”凡卦体卦德皆从内说出去。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>王氏说最足以破卦变之支离，得易象之本旨</p><p>大亨贞，无咎，而天下随时</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>王肃本“时”作“之”，今当从之。释卦辞，言能如是则天下之所从也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>卦所以为随，以刚来而下柔，动而说也。谓干之上九来居坤之下，坤之初六往居干之上，以阳刚来下于阴柔，是以上下下，以贵下贱。能如是，物之所说随也。又下动而上说，动而可说也，所以随也。如是，则可大亨而得正，能大亨而得正，则为无咎。不能亨不得正，则非可随之道，岂能使天下随之乎？天下所随者时也，故云“天下随时”。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：大亨贞正，无有咎害，而天下随之。以正道相随，故随之者广。若不以大亨贞无咎，而以邪僻相随，则天下不从也。</p></li><li><p>乔氏中和曰：刚下柔而阳随阴，以我随物，则物自随我而动，罔不说，此大亨之正道也。人同此心，天下有不随之者哉？</p></li></ul><p>随时之义大矣哉</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>王肃本“时”字在“之”字下，今当从之。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>君子之道，随时而动，从宜适变，不可为典要。非造道之深，知几能权者，不能与于此也。故赞之曰：“随时之义大矣哉！”凡赞之者，欲人知其义之大，玩而识之也。此赞随时之义大，与豫等诸卦不同。诸卦时与义是两事。</p><p>初九：官有渝，贞吉，出门交有功</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>卦以物随为义，爻以随物为义。初九以阳居下，为震之主，卦之所以为随者也。既有所随，则有所偏主而变其常矣。惟得其正则吉，又当出门以交，不私其随，则有功也。故其象占如此，亦因以戒之。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>九居随时而震体，且动之主有所随者也。官主守也，既有所随，是其所主守有变易也，故曰“官有渝贞吉”。所随得正则吉也，有渝而不得正，乃过动也。出门交有功，人心所从，多所亲爱者也。常人之情，爱之则见其是，恶之则见其非。故妻孥之言虽失而多从，所憎之言虽善为恶也。苟以亲爱而随之，则是私情所与，岂合正理？故出门而交，则有功也。出门谓非私昵交，不以私，故其随当而有功。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：人心所主谓之官，渝，变也。初九无应，无所偏系，可随则随，是所执之志能渝变也。唯正是从，故贞吉也。所随不以私，见善则往随之，以此出门交，获其功。</p></li><li><p>房氏乔曰：出门有功，先择后交。</p></li><li><p>石氏介曰：阳在二阴之下，以刚下柔，孰不从之？故出门则人从之。</p></li><li><p>朱子语类问：初九“官有渝，贞吉，出门交有功”。官是主字之义，是一卦之主首。变得正便吉，不正便凶。曰：是如此。</p></li><li><p>张氏清子曰：官主也，渝变也。当随之初，刚来下柔，为震之主，震动也。官有渝，是主守有变动之象，随时而动，有所变易，不能保其无偏也。故必变而从正则吉。出门而交，即同人于门之意。得随之正而不牵于私，则有功而无失矣。</p></li><li><p>俞氏琰曰：随之六爻，专取相比相随，不取其应。初九震体，震以刚爻为主官也。官虽贵乎有守，然处随之时，不可守常而不知变。变者何？趋时从权，不以主自居也。故曰“官有渝”。初九乃成卦之主爻，主不可以随人，故不言随而言交。系者，随而攀恋不舍之义。六二、六三、上六，其性皆阴柔而攀恋相随不舍，故皆言系。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>阳为阴主，故曰官。夫阳为主而阴随之者，正也。今以刚而下柔，是其变也，故曰“官有渝”。然当随而随变，而不失其正者也，故可以得吉，而出门交有功。</p><p>象曰：官有渝，从正吉也；出门交有功，不失也</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>既有随而变，必所从得正则吉也；所从不正，则有悔吝。出门而交，非牵于私，其交必正矣。正则无失而有功。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>俞氏琰曰 ：卦以阳爻为主，为主者故不当随人，而阳亦不当随阴。然以正从正，则随道之当然也。</li></ul><p>六二：系小子，失丈夫</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>初阳在下而近，五阳正应而远，二阴柔不能自守以须正应，故其象如此，凶吝可知，不假言矣。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二应五而比初，随先于近柔，不能固守，故为之戒云：“若系小子，则失丈夫也。”初阳在下，小子也；五正应在上，丈夫也。二若志系于初，则失九五之正应，是失丈夫也。系小子而失丈夫，舍正应而从不正，其咎大矣。二有中正之德，非必至如是也，在随之时，当为之戒也。</p><p>象曰：系小子，弗兼与也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>人之所随，得正则远邪，从非则失。是无两从之理，二苟系初则失五矣，弗能兼与也。所以戒人从正当专一也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>九五、六二之应同也，在比、萃则吉，在同人则吝，在随则系小子而吝，亦可知矣。所以然者，皆因卦义而变。卦义以刚下柔，而此爻以柔从刚，于时义则不合，而不失乎阳唱阴随之常理，故圣人犹嘉其志焉。</p><p>六三：系丈夫，失小子，随有求得，利居贞</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>丈夫谓九四，小子亦谓初也。三近系四而失于初，其象与六二正相反。四阳当任而已，随之有求必得，然非正应，故有不正而为邪媚之嫌。故其占如此，而又戒以居贞也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>丈夫九四也，小子初也。阳之在上者，丈夫也；居下者，小子也。三虽与初同体而切近于四，故系于四也。大抵阴柔不能自立，常亲系于所近者。上系于四，故下失于初。舍初从上，得随之宜也。上随则善也，如昏之随明，事之从善，上随也。背是从非，舍明逐暗，下随也。四亦无应无随之者也，近得三之随，必与之亲善，故三之随四，有求必得也。人之随于上，而上与之，是得所求也。又凡所求者可得也。虽然，固不可非理枉道以随于上，苟取爱说以遂所求，如此乃小人邪谄趋利之为也。故云“利居贞”，自处于正则所谓有求而必得者，乃正事君子之随也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：阴随阳，三之上无应，上系于四，失初小子，故系丈夫失小子。</p></li><li><p>王氏弼曰：虽体下卦，二已据初，将何所附，故舍初系四，志在丈夫。四俱无应，亦欲于已随之，则得其所求矣，故曰“随有求得也”。应非其正，以系于人，何可以妄，故“利居贞”也。初处已下，四处已上，故曰“系丈夫失小子”。</p></li><li><p>陆氏希声曰：三非正而随，其义可尚者，以承阳为顺也。</p></li></ul><p>象曰：系丈夫，志舍下也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>既随于上，则是其志舍下而不从也。舍下而从上，舍卑而从高也，于随为善矣。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>黄氏淳耀曰 ：人之取舍系乎志。三志既系于四，则所舍必在于初矣；在二则因系以明其弗兼；在三则因舍以坚其所系。</li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>此爻何以知其志舍下？以无刚来下之，则必从上之刚矣。四近而初远，故也。卦义以刚下柔，而此爻以柔从刚，于时义则不合，而不失乎阳唱阴随之常理，故圣人犹嘉其志焉。</p><p>九四：随有获，贞凶，有孚在道以明，何咎</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>九四以刚居上之下，与五同德，故其占随而有获。然势陵于五，故虽正而凶。惟有孚在道而明，则上安而下从之，可以无咎也。占者当时之任，宜审此戒。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>九四以阳刚之才处臣位之极，若于随有获，则虽正亦凶。有获谓得天下之心，随于已为臣之道。当使恩威一出于上，众心皆随于君。若人心从已，危疑之道也，故凶。居此地者奈何？惟孚诚积于中，动为合于道，以明哲处之，则又何咎？古之人有行之者，伊尹、周公、孔明是也。皆德及于民而民随之，其得民之随，所以成其君之功，致其国之安。其至诚存乎中，是有孚也。其所施为无不中道，在道也。惟其明哲，故能如是，以明也。复何过咎之有？是以下信而上不疑，位极而无逼上之嫌，势重而无专权之过，非圣人大贤则不能也。其次如唐之郭子仪，威震主而主不疑，亦由中有诚孚而处无甚失也。非明哲能如是乎？</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：谓获三也。</p></li><li><p>王氏弼曰：处说之初，下据二阴。三求系已，不距则获，故曰“随有获也”。居于臣地，履非其位，以擅其民，失于臣道，故曰“贞凶”。虽违常义，心存公诚，著信在道，以明其功，何咎之有？</p></li><li><p>郭氏雍曰：六三“随有求得”，盖随人而有得者。九四“随有获”，盖以得人之随为获也。夫尊近之臣，势疑于君，又获天下之随，守此为贞，则凶矣。是必有至诚之道，足以使天下无疑焉，斯无咎。</p></li><li><p>徐氏几曰：六三、九四相比相从，三言“有得”者，得乎四也；四言“有获”者，获乎三也。</p></li><li><p>龚氏焕曰：随卦诸爻皆以阴阳相随为义。三、四皆无正应，相比而相随者也。然六三上而从阳，理之正也；九四下为阴从，固守则凶。若心所孚信在于道焉，以明自处，何咎之有？</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>郭氏、徐氏、龚氏之说皆与卦意爻义相合，龚氏尤简明也。</p><p>象曰：随有获，其义凶也；有孚在道，明功也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>居近君之位而有获，其义固凶。能有孚而在道，则无咎，盖明哲之功也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>袁氏枢曰 ：其义凶者，有凶之理也。处得其道，如下所云，则无咎矣。</li></ul><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>义者，谓卦义也。卦义刚下于柔，而四刚为柔随，且处近君之地，尤有招纳之嫌，故曰其义凶也。</p><p>九五：孚于嘉，吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>阳刚中正，下应中正，是信于善也。占者如是其吉，宜矣。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>九五居尊得正而中实，是其中诚在于随善，其吉可知。嘉善也，自人君至于庶人，随道之吉，惟在随善而已。下应二之正中，为随善之义。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>杨氏万里曰：九五以阳刚居兑之中正，为一卦说随之主。此圣君至诚乐从天下之善者也，吉孰大焉？孚诚也，嘉善也。</p></li><li><p>王氏应麟曰：信君子者，治之原。随之九五曰“孚于嘉吉”，信小人者，乱之机。兑之九五曰“孚于剥有厉”。</p></li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>九五阳刚中正，下应二之阴柔中正，体现了随善之道，故为吉兆。</p><p>象曰：孚于嘉，吉；位正中也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>处正中之位，由正中之道，孚诚所随者，正中也。所谓嘉也，其吉可知。所孚之嘉，谓六二也。随以得中为善，随之所防者过也。盖心所说随，则不知其过矣。</p><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>当随之时，居尊位而有正中之德，则所孚者皆善矣。初、五皆言吉，而五尤吉，以其正中故尔。</p><p>上六：拘系之，乃从维之，王用亨于西山</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>居随之极，随之固结而不可解者也。诚意之极，可通神明，故其占为王用亨于西山。亨亦当作祭享之享。自周而言，岐山在西，凡筮祭山川者得之，其诚意如是，则吉也。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>上六以柔顺而居随之极，极乎随者也。拘系之谓，随之极如拘持縻系之，乃从维之又从而维系之也。谓随之固结如此。王用亨于西山，随之极如是。昔者太王用此道亨王业于西山。太王避狄之难，去豳来岐，豳人老稚扶携以随之如归市，盖其人心之随固结如此。用此故能亨盛其王业于西山。西山，岐山也。周之王业盖兴于此。上居随极固为太过，然在得民之随与随善之固如此，乃为善也。施于他则过矣。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吕民祖谦曰：拘系而不可解，随之极者也。如有客诗言“授之絷，以絷其马”，白驹诗“絷之维之，以永今朝”，正合此爻。</p></li><li><p>项氏安世曰：大有九三“公用亨于天子”，随上六“王用亨于西山”，益六二“王用亨于帝”，升六四“王用亨于岐山”，四爻句法皆同。古文“亨”即“享”字，今独益作“享”读，俗师不识古字，独于“享帝”不敢作“亨帝”也。</p></li></ul><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>上六爻描述了随之极的情境，象征民心固结，难以解脱。这种随善的固结，可以带来王业的兴盛，如周太王避狄来岐，得民心之随，从而兴盛王业于西山（岐山）。此爻强调的是随善之固与民心之随的重要性，与九五爻的“孚于嘉”相呼应，共同体现了随卦的主旨。</p><p>象曰：拘系之上，穷也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>穷极也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>随之固如拘系，维持随道之穷极也。</p><h3 id="案-10" tabindex="-1">案 <a class="header-anchor" href="#案-10" aria-label="Permalink to “案”">​</a></h3><p>上穷则有高亢之意，在人如绝世离群，往而不返者是也。卦之阴爻皆云系，至上六独曰拘系，之故夫子发明其义，以为因上六之不易系也。</p><p>总论</p><p>王氏宗传曰：“随之六爻，其半阴也，其半阳也。阳刚之才，则有所随而无所系，初九、九四、九五是也。故初之有渝，四之有获，五之孚于嘉，此有所随而无所系者也。以柔从之才而当随之时，则均不免于有所系，六二、六三、上六是也。故二则系小子失丈夫，三则系丈夫失小子，上则曰拘系之，此均不免于有所系者也。”</p>',124)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
